import{_ as a,o as e,c as n,a0 as l}from"./chunks/framework.DqMqoJl9.js";const p="/assets/%E5%A4%9A%E6%A0%87%E7%AD%BE%E9%A1%B5%E5%85%B1%E4%BA%AB%E8%BF%9B%E7%A8%8B%E9%97%AE%E9%A2%98_20191111135733.DAEwH1mk.png",o="/assets/%E5%A4%9A%E6%A0%87%E7%AD%BE%E9%A1%B5%E5%85%B1%E4%BA%AB%E8%BF%9B%E7%A8%8B%E9%97%AE%E9%A2%98_20191108143227.DWEWDh2V.png",t="/assets/%E5%A4%9A%E6%A0%87%E7%AD%BE%E9%A1%B5%E5%85%B1%E4%BA%AB%E8%BF%9B%E7%A8%8B%E9%97%AE%E9%A2%98_20191111103908.fxwbhuHY.png",r="/assets/%E5%A4%9A%E6%A0%87%E7%AD%BE%E9%A1%B5%E5%85%B1%E4%BA%AB%E8%BF%9B%E7%A8%8B%E9%97%AE%E9%A2%98_20191111103526.BE-R9MEy.png",i="/assets/%E5%A4%9A%E6%A0%87%E7%AD%BE%E9%A1%B5%E5%85%B1%E4%BA%AB%E8%BF%9B%E7%A8%8B%E9%97%AE%E9%A2%98_20191111113330.CYMOYb0n.gif",c="/assets/%E5%A4%9A%E6%A0%87%E7%AD%BE%E9%A1%B5%E5%85%B1%E4%BA%AB%E8%BF%9B%E7%A8%8B%E9%97%AE%E9%A2%98_20191111113712.B3CGuFkq.png",u="/assets/%E5%A4%9A%E6%A0%87%E7%AD%BE%E9%A1%B5%E5%85%B1%E4%BA%AB%E8%BF%9B%E7%A8%8B%E9%97%AE%E9%A2%98_20191111144740.By5Ub76R.png",_=JSON.parse('{"title":"多页面共用进程问题","description":"","frontmatter":{},"headers":[],"relativePath":"others/process.md","filePath":"others/process.md","lastUpdated":1791573371000}'),E={name:"others/process.md"};function A(d,s,b,h,m,B){return e(),n("div",null,[...s[0]||(s[0]=[l('<h1 id="多页面共用进程问题" tabindex="-1">多页面共用进程问题 <a class="header-anchor" href="#多页面共用进程问题" aria-label="Permalink to &quot;多页面共用进程问题&quot;">​</a></h1><p>最近开发的编程平台项目出现过一个怪异的问题，在作品详情和编辑器页面，会偶现页面崩溃的问题。报一个错误，如下：</p><p><img src="'+p+'" alt=""></p><p>经过一段时间的观察，找到了这个问题出现的规律：打开第 5 个作品详情页面时就会出现这个错误。</p><p>那么为什么打开第五个标签就会出现这个错误，并且只有在标签内打开新的标签才会出现这个问题，而手动新建标签再输地址打开的页面不会出现问题？</p><p>这需要从进程和线程说起～</p><h2 id="_1-进程和线程" tabindex="-1">1 进程和线程 <a class="header-anchor" href="#_1-进程和线程" aria-label="Permalink to &quot;1 进程和线程&quot;">​</a></h2><ul><li>进程是 cpu 资源分配的最小单位（是能拥有资源和独立运行的最小单位）</li><li>线程是 cpu 调度的最小单位（线程是建立在进程的基础上的一次程序运行单位，一个进程中可以有多个线程）</li></ul><p>进程和线程的特点：</p><ul><li>进程中任意线程出错，都会导致进程崩溃</li><li>线程之间可以共享进程中的数据</li><li>一个进程关闭后，操作系统会回收其内存</li><li>进程之间内容相互隔离，避免互相影响</li></ul><h2 id="_2-chrome-的进程" tabindex="-1">2 chrome 的进程 <a class="header-anchor" href="#_2-chrome-的进程" aria-label="Permalink to &quot;2 chrome 的进程&quot;">​</a></h2><p>浏览器是多进程的</p><p>浏览器之所以能够运行，是因为系统给它的进程分配了资源（cpu、内存）</p><p><strong>一般</strong>情况每打开一个 Tab 页，就相当于创建了一个独立的浏览器进程（也有多标签属于同一个进程的情况）。</p><p><strong>Chrome 包括的进程：</strong></p><ul><li>浏览器进程：负责界面显示、用户交互、子进程管理等功能</li><li>渲染进程：负责解析 html,css,js；排版引擎 Blink 与 JS 的 V8 引擎都在该进程中；运行在沙箱模式下</li><li>GPU 进程：独立于其他进程，专用于处理 GPU 任务，比如 webgl 渲染，css3 动画</li><li>网络进程：负责页面网络资源加载</li><li>插件进程：负责插件的运行，插件易崩溃，所以隔离出来</li></ul><p><img src="'+o+'" alt=""></p><p><strong>浏览器多进程的优势：</strong></p><ul><li>避免单个页面崩溃影响整个浏览器</li><li>避免第三方插件奔溃影响整个浏览器</li><li>多进程充分利用多核优势</li><li>方便使用沙盒模型隔离插件等进程，提高浏览器稳定性</li></ul><h2 id="_3-渲染进程" tabindex="-1">3 渲染进程 <a class="header-anchor" href="#_3-渲染进程" aria-label="Permalink to &quot;3 渲染进程&quot;">​</a></h2><p>详情看这篇文章：<a href="https://juejin.im/post/5a6547d0f265da3e283a1df7" target="_blank" rel="noreferrer">https://juejin.im/post/5a6547d0f265da3e283a1df7</a></p><p>页面的渲染，JS 的执行，事件的循环，都在渲染进程内进行，浏览器的渲染进程是多线程的。</p><p>渲染进程有以下主要的线程：</p><ul><li>GUI 渲染线程</li><li>JS 引擎线程，GUI 渲染线程与 JS 引擎线程是互斥的，一个 Tab 页（renderer 进程）中无论什么时候都只有一个 JS 线程在运行 JS 程序</li><li>事件触发线程</li><li>定时触发器线程</li><li>异步 http 请求线程</li></ul><h2 id="_4-多标签共用进程的情况" tabindex="-1">4 多标签共用进程的情况 <a class="header-anchor" href="#_4-多标签共用进程的情况" aria-label="Permalink to &quot;4 多标签共用进程的情况&quot;">​</a></h2><p>一般情况下，每打开一个浏览器标签页（手动打开新标签，通过在地址栏输入 URL），会新开一个独立进程，即使两个标签页打开的是同一个页面。</p><p><img src="'+t+'" alt=""></p><p>(可以看到打开的是同一个页面，但是分配了两个进程)</p><p>但是通过一个标签页打开另一个标签页时，会将两个标签共用一个进程。</p><p>比如：</p><ul><li>指定了 target=&quot;_blank&quot; 的 a 标签（同源的地址）</li><li>window.open()（同源的地址）</li><li>iframe 内嵌页面（同源的 iframe 不会分配新的进程，而非同源 iframe 页面作为一个“辅助框架”，会分配一个独立进程）</li></ul><p><img src="'+r+'" alt=""></p><p>(这两个页面共用了一个进程)</p><blockquote><p>那么为什么会出现这种情况呢？当一个标签页打开另一个标签页时，这两个标签可能需要互相通信（可以通过 window.opener 获取父页面的全局对象），那么新标签页就不能运行在独立的进程中</p></blockquote><p>如何避免共用进程的情况呢？下面摘抄自 MDN 关于 a 标签的文档:</p><blockquote><p>Note: Linking to another page using target=&quot;_blank&quot; will run the new page on the same process as your page. If the new page is executing expensive JS, your page&#39;s performance may suffer. To avoid this use rel=noopener.</p></blockquote><p>在 a 标签上加上 rel=noopener 就可以在打开新标签时新分配一个进程。</p><blockquote><p>经过测试，这个属性在 chrome 和 firefox 上表现正常，在 safari 上无效</p></blockquote><h3 id="_4-1-共用进程造成页面阻塞的情况" tabindex="-1">4.1 共用进程造成页面阻塞的情况 <a class="header-anchor" href="#_4-1-共用进程造成页面阻塞的情况" aria-label="Permalink to &quot;4.1 共用进程造成页面阻塞的情况&quot;">​</a></h3><p>多标签共用一个进程肯定是有隐患的，假如其中一个页面有很大的计算量，那么就可能会造成页面卡顿，并且影响的是所有共用这一个进程的页面。</p><p>下面参考一个实例：</p><p><img src="'+i+'" alt=""></p><p>上图中点击 &quot;js 阻塞页面&quot; 会执行一个死循环卡死页面，红色的方块是一个 css 动画。</p><p>现在打开 3 个标签页，其中 1、2 为同一个进程，3 为独立的进程。</p><p><img src="'+c+'" alt=""></p><p>让 js 阻塞页面后，观察实验结果：</p><ul><li>1 页面动画停止</li><li>2 页面动画停止</li><li>3 页面动画正常</li></ul><h2 id="_5-audiocontext-的实例数量限制" tabindex="-1">5 AudioContext 的实例数量限制 <a class="header-anchor" href="#_5-audiocontext-的实例数量限制" aria-label="Permalink to &quot;5 AudioContext 的实例数量限制&quot;">​</a></h2><p>回到编程平台出现的那个问题。</p><p>通过错误提示，顺着找到了错误的原因，是由于 AudioContext 创建的实例为 null 造成的。</p><p>通过上面介绍的浏览器进程和线程的特性，猜测出现这个问题是由于多标签共用进程造成的。也就是说在同一个进程内创建 AudioContext 的实例有数量限制。</p><p>找了一些资料，并没有找到比较官方的说明，只找到一个类似问题的回答：</p><p><img src="'+u+`" alt=""></p><p>那么就需要测试一下：</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6A737D;">// 创建 AudioContext 实例，并创建 buffer</span></span>
<span class="line"><span style="color:#D73A49;">function</span><span style="color:#6F42C1;"> createContext</span><span style="color:#24292E;">() {</span></span>
<span class="line"><span style="color:#D73A49;">  let</span><span style="color:#24292E;"> Context </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> window.AudioContext </span><span style="color:#D73A49;">||</span><span style="color:#24292E;"> window.webkitAudioContext;</span></span>
<span class="line"><span style="color:#D73A49;">  let</span><span style="color:#24292E;"> context </span><span style="color:#D73A49;">=</span><span style="color:#D73A49;"> new</span><span style="color:#6F42C1;"> Context</span><span style="color:#24292E;">();</span></span>
<span class="line"><span style="color:#D73A49;">  let</span><span style="color:#24292E;"> buffer </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> context.</span><span style="color:#6F42C1;">createBuffer</span><span style="color:#24292E;">(</span><span style="color:#005CC5;">1</span><span style="color:#24292E;">, </span><span style="color:#005CC5;">1</span><span style="color:#24292E;">, context.sampleRate);</span></span>
<span class="line"><span style="color:#D73A49;">  let</span><span style="color:#24292E;"> source </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> context.</span><span style="color:#6F42C1;">createBufferSource</span><span style="color:#24292E;">();</span></span>
<span class="line"></span>
<span class="line"><span style="color:#24292E;">  source.buffer </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> buffer;</span></span>
<span class="line"><span style="color:#24292E;">  source.</span><span style="color:#6F42C1;">connect</span><span style="color:#24292E;">(context.destination);</span></span>
<span class="line"><span style="color:#24292E;">  source.</span><span style="color:#6F42C1;">start</span><span style="color:#24292E;">(</span><span style="color:#005CC5;">0</span><span style="color:#24292E;">);</span></span>
<span class="line"><span style="color:#24292E;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>测试结果：</p><ul><li>chrome 可以创建 1 千个以上的实例（可能无限制）</li><li>firefox 同 chrome</li><li>safari 最多创建 4 个实例</li></ul><p>经过测试，可以确定造成这个看起来很怪异的问题的原因就是： safari 在一个进程内最多只能创建 4 个 AudioContext 实例，多于 4 个则返回 null</p><p>参考资料：</p><ul><li><a href="https://juejin.im/post/5a6547d0f265da3e283a1df7" target="_blank" rel="noreferrer">https://juejin.im/post/5a6547d0f265da3e283a1df7</a></li><li><a href="https://juejin.im/post/5d5a330ae51d453bdb1d9b4e" target="_blank" rel="noreferrer">https://juejin.im/post/5d5a330ae51d453bdb1d9b4e</a></li><li><a href="https://juejin.im/post/5bd7c761518825292d6b0217" target="_blank" rel="noreferrer">https://juejin.im/post/5bd7c761518825292d6b0217</a></li><li><a href="https://developer.mozilla.org/zh-CN/docs/Web/API/AudioContext" target="_blank" rel="noreferrer">https://developer.mozilla.org/zh-CN/docs/Web/API/AudioContext</a></li></ul>`,60)])])}const y=a(E,[["render",A]]);export{_ as __pageData,y as default};
